// ---------- Étape 2 : l'explosion de P(25, k) ----------
// Même formule qu'au 15-puzzle : P(25,k) placements des k tuiles × (25-k) positions de la case vide.
// On calcule en long : dès k = 6 le résultat dépasse la capacité d'un int.
long PLong(int n, int k) { long r = 1; for (int i = 0; i < k; i++) r *= (n - i); return r; }
long PdbSize24(int k) => PLong(CELLS5, k) * (CELLS5 - k);

Console.WriteLine("Taille d'une PDB du 24-puzzle (1 octet par état abstrait) :");
foreach (int k in new[] { 3, 4, 5, 6, 7 })
    Console.WriteLine($" groupe de {k} tuiles : P(25,{k}) x {CELLS5 - k,2} = {PdbSize24(k),18:N0} états ≈ {PdbSize24(k) / 1e9,6:F2} Go");

long total6667 = 3 * PdbSize24(6) + PdbSize24(7);
Console.WriteLine($"Partition 6-6-6-7 demandée : {total6667:N0} états ≈ {total6667 / 1e9:F1} Go de RAM");
Console.WriteLine($"Plus grand tableau autorisé par .NET : Array.MaxLength = {Array.MaxLength:N0} cases");
Console.WriteLine($"=> un seul groupe de 6 ({PdbSize24(6):N0} états) dépasse déjà cette limite : 6-6-6-7 est infaisable tel quel sur un PC.");
