};

var heuristics24 = new List<(string name, Func<int[], int> h)> { ("Manhattan", (Func<int[], int>)Manhattan24) };
foreach (var p in PDB24) { var pp = p; heuristics24.Add(($"PDB {pp.name}", (Func<int[], int>)(st => HAdditive24(st, pp.groups, pp.tables)))); }

var bench24 = new List<(string inst, string heur, int h0, int? opt, long nodes, double sec)>();
foreach (var (iname, s) in INSTANCES24) {
    Console.WriteLine($"{iname} :");
    foreach (var (hname, h) in heuristics24) {
        var swI = System.Diagnostics.Stopwatch.StartNew();
        var (opt, nodes) = IdaStar24(s, h);
        swI.Stop();
        bench24.Add((iname, hname, h(s), opt, nodes, swI.Elapsed.TotalSeconds));
        string res = opt.HasValue ? $"optimal = {opt,3}, {nodes,12:N0} nœuds" : $"NON RÉSOLU, budget de {nodes:N0} nœuds épuisé";
        Console.WriteLine($"   {hname,-15} h(départ) = {h(s),3} | {res} ({swI.Elapsed.TotalSeconds:F1} s)");
    }
}

